insert into organizations (id, slug, name, short_name, description, website, primary_color, accent_color, sort_order) values
  ('eabef21d-86c5-4768-a789-8c5b2d8bbe83', 'bassmaster', 'Bass Anglers Sportsman Society', 'Bassmaster', 'Founded in 1968, B.A.S.S. runs the Bassmaster Elite Series, the Opens, and the sport''s defining championship — the Bassmaster Classic.', 'https://www.bassmaster.com', '#0B1622', '#E8472B', 1),
  ('9071bd17-d28b-4080-afbd-5bac4972b1f2', 'mlf', 'Major League Fishing', 'MLF', 'Home of the catch-weigh-immediately-release format, the Bass Pro Tour, the Invitationals, the Toyota Series and the grassroots Phoenix Bass Fishing League.', 'https://majorleaguefishing.com', '#0A1A2F', '#1FA2E0', 2),
  ('1e1856b0-4c04-4d5a-a01c-b5a0c0023e02', 'npfl', 'National Professional Fishing League', 'NPFL', 'An angler-first professional tour founded in 2021 on a flat entry fee, a capped field, and a published payout table.', 'https://npfl.com', '#14241A', '#C8A227', 3)
insert into series (id, org_id, slug, name, short_name, level, format, description, sort_order) values
  ('86633cd1-2891-4361-a931-84ee070e218f', 'eabef21d-86c5-4768-a789-8c5b2d8bbe83', 'bassmaster-elite-series', 'Bassmaster Elite Series', 'Elite Series', 'professional', 'bag_limit_5', 'The top rung at B.A.S.S. — roughly 100 of the best boaters in the world over an eight- or nine-event season, racing for Angler of the Year and a Classic berth.', 0),
  ('3b0d5a91-c0f4-437b-acf1-ed8de55eb429', 'eabef21d-86c5-4768-a789-8c5b2d8bbe83', 'bassmaster-open-series', 'Bassmaster Open Series', 'Opens', 'semi_pro', 'bag_limit_5', 'The qualifying path to the Elites. Fish one division or fish them all; the top finishers earn Elite invitations.', 1),
  ('0468eeb2-fba3-4840-adda-85f2ea82ae09', 'eabef21d-86c5-4768-a789-8c5b2d8bbe83', 'bassmaster-classic', 'Bassmaster Classic', 'Classic', 'championship', 'bag_limit_5', 'The world championship of bass fishing. Roughly 55 qualifiers, three days, one trophy.', 2),
  ('a7690223-69eb-4e60-a769-5912c395d8ba', 'eabef21d-86c5-4768-a789-8c5b2d8bbe83', 'bass-nation', 'B.A.S.S. Nation', 'Nation', 'amateur', 'bag_limit_5', 'The grassroots club circuit — state federations feeding regional championships and a shot at the Classic.', 3),
  ('f01fdb6b-851a-4ebd-a86d-2dbe473773c9', 'eabef21d-86c5-4768-a789-8c5b2d8bbe83', 'bassmaster-college-series', 'Bassmaster College Series', 'College', 'college', 'bag_limit_5', 'Two-angler university teams fishing for a national title and a Classic berth for the winner.', 4),
  ('2197792c-14c9-42e6-a242-a760b9d16909', 'eabef21d-86c5-4768-a789-8c5b2d8bbe83', 'bassmaster-high-school-series', 'Bassmaster High School Series', 'High School', 'high_school', 'bag_limit_5', 'Two-angler high school teams with a boat captain, fishing state and national events.', 5),
  ('6eb317aa-c021-47e4-ab62-6945ed680d54', '9071bd17-d28b-4080-afbd-5bac4972b1f2', 'bass-pro-tour', 'Bass Pro Tour', 'BPT', 'professional', 'catch_weigh_release', 'MLF''s flagship: 80 anglers, no five-fish limit, every scorable bass counts on SCORETRACKER as it is caught.', 6),
  ('2c3f8d1f-f1c2-4f34-a4c8-9a0523bd4966', '9071bd17-d28b-4080-afbd-5bac4972b1f2', 'tackle-warehouse-invitationals', 'Tackle Warehouse Invitationals', 'Invitationals', 'professional', 'bag_limit_5', 'The direct qualifier to the Bass Pro Tour — traditional five-fish-limit events with a 150-angler field.', 7),
  ('3a6377af-ce05-4402-abd3-751e3c4b435e', '9071bd17-d28b-4080-afbd-5bac4972b1f2', 'toyota-series', 'Toyota Series', 'Toyota Series', 'semi_pro', 'bag_limit_5', 'Regional three-day events with a boater and co-angler division, feeding a year-end championship.', 8),
  ('33acc383-0493-4385-a4ea-4225bb40dc91', '9071bd17-d28b-4080-afbd-5bac4972b1f2', 'phoenix-bass-fishing-league', 'Phoenix Bass Fishing League', 'BFL', 'amateur', 'bag_limit_5', 'The entry point to tournament bass fishing — 24 regional divisions of one-day weekend events.', 9),
  ('77bad0d9-243b-4cc3-a37c-0f57b97685a3', '9071bd17-d28b-4080-afbd-5bac4972b1f2', 'abu-garcia-college-fishing', 'Abu Garcia College Fishing', 'College', 'college', 'bag_limit_5', 'Two-angler collegiate teams across four conferences and a national championship.', 10),
  ('55696a15-bbde-48cc-a152-c6c821314df7', '1e1856b0-4c04-4d5a-a01c-b5a0c0023e02', 'npfl-tour', 'NPFL Tour', 'NPFL Tour', 'professional', 'bag_limit_5', 'A capped 120-boat professional field, flat entry fees, and a payout table published before the season starts.', 11),
  ('461fcc75-6b6f-483d-a349-99fe1c631206', '1e1856b0-4c04-4d5a-a01c-b5a0c0023e02', 'npfl-championship', 'NPFL Championship', 'Championship', 'championship', 'bag_limit_5', 'The season-ending shootout for the NPFL''s top points earners.', 12)
